// Initialize world evolution cycle
const evolutionConfig = {
  cycleTime: new Date().toISOString(),
  evolutionType: 'scheduled',
  worldEffects: {
    natural_processes: true,
    npc_autonomy: true,
    faction_dynamics: true,
    economic_changes: true,
    environmental_effects: true
  },
  intensity: 'normal', // low, normal, high
  focus_areas: ['locations', 'npcs', 'factions', 'economy', 'environment']
};

// Get all active campaigns
const activeCampaigns = await $this.helpers.httpRequestWithAuthentication.call(
  this.getNode('campaign-database'),
  'get',
  '/api/campaigns/active'
);

return [{
  json: {
    ...evolutionConfig,
    campaigns: activeCampaigns.data || [],
    totalCampaigns: activeCampaigns.data?.length || 0
  }
}];

// Process campaign data and prepare for evolution
const campaigns = $input.first().json.results || [];
const evolutionConfig = $input.first().json;

const processedCampaigns = campaigns.map(campaign => {
  const { campaignId, worldState, lastEvolution } = campaign;

  // Calculate evolution factors based on time since last evolution
  const now = new Date();
  const lastEvolutionDate = lastEvolution ? new Date(lastEvolution) : new Date(now.getTime() - 24 * 60 * 60 * 1000);
  const hoursSinceEvolution = (now - lastEvolutionDate) / (1000 * 60 * 60);

  const evolutionFactors = {
    time_multiplier: Math.min(hoursSinceEvolution / 4, 3), // Cap at 3x
    natural_decay: hoursSinceEvolution > 8,
    growth_opportunity: hoursSinceEvolution > 12,
    major_event_chance: Math.min(hoursSinceEvolution / 48, 0.3)
  };

  return {
    campaignId,
    currentWorldState: worldState || {},
    lastEvolution,
    evolutionFactors,
    evolutionPriority: calculateEvolutionPriority(worldState, evolutionFactors)
  };
});

// Sort by evolution priority
processedCampaigns.sort((a, b) => b.evolutionPriority - a.evolutionPriority);

function calculateEvolutionPriority(worldState, factors) {
  let priority = factors.time_multiplier * 10;

  // Add priority based on world state complexity
  if (worldState.locations?.length > 10) priority += 5;
  if (worldState.npcs?.length > 20) priority += 5;
  if (worldState.factions?.length > 5) priority += 3;
  if (worldState.activeQuests?.length > 0) priority += 8;

  // Add priority for dynamic worlds
  if (worldState.worldEvents?.length > 5) priority += 4;
  if (factors.major_event_chance > 0.2) priority += 6;

  return priority;
}

return [{
  json: {
    ...evolutionConfig,
    campaigns: processedCampaigns,
    totalCampaigns: processedCampaigns.length,
    evolution_cycle_id: `evolution_${Date.now()}`
  }
}];

// Generate natural world evolution events
const campaign = $input.first().json;
const { campaignId, currentWorldState, evolutionFactors } = campaign;

const evolutionEvents = [];

// 1. Natural Environment Changes
if (evolutionFactors.natural_decay || Math.random() < 0.3) {
  evolutionEvents.push(generateEnvironmentChange(currentWorldState));
}

// 2. NPC Autonomous Actions
if (currentWorldState.npcs && currentWorldState.npcs.length > 0) {
  const activeNPCs = currentWorldState.npcs.filter(npc => 
    npc.status === 'alive' && Math.random() < 0.2
  );

  activeNPCs.forEach(npc => {
    evolutionEvents.push(generateNPCAutonomousAction(npc, currentWorldState));
  });
}

// 3. Faction Dynamics
if (currentWorldState.factions && currentWorldState.factions.length > 1) {
  currentWorldState.factions.forEach(faction => {
    if (Math.random() < 0.15) {
      evolutionEvents.push(generateFactionAction(faction, currentWorldState));
    }
  });
}

// 4. Economic Fluctuations
if (Math.random() < 0.25) {
  evolutionEvents.push(generateEconomicChange(currentWorldState));
}

// 5. Random World Events
if (Math.random() < evolutionFactors.major_event_chance) {
  evolutionEvents.push(generateMajorWorldEvent(currentWorldState));
}

function generateEnvironmentChange(worldState) {
  const environments = ['forest', 'mountain', 'desert', 'ocean', 'city', 'dungeon', 'ruins'];
  const changes = ['weather_shift', 'growth', 'decay', 'discovery', 'natural_disaster'];
  const weather_types = ['clear', 'rain', 'storm', 'fog', 'snow', 'heatwave'];

  const environment = environments[Math.floor(Math.random() * environments.length)];
  const change = changes[Math.floor(Math.random() * changes.length)];
  const weather = weather_types[Math.floor(Math.random() * weather_types.length)];

  return {
    type: 'environment_change',
    subtype: change,
    environment,
    weather: weather,
    impact: calculateEnvironmentalImpact(change, environment),
    description: `The ${environment} experiences ${change} with ${weather} conditions`,
    affected_locations: worldState.locations?.filter(loc => 
      loc.type?.includes(environment) || loc.properties?.environment === environment
    ).map(loc => loc.id) || [],
    duration: generateDuration(change),
    timestamp: new Date().toISOString()
  };
}

function generateNPCAutonomousAction(npc, worldState) {
  const actions = ['movement', 'interaction', 'skill_use', 'resource_gathering', 'resting'];
  const action = actions[Math.floor(Math.random() * actions.length)];

  return {
    type: 'npc_action',
    subtype: action,
    npc_id: npc.id,
    npc_name: npc.name,
    current_location: npc.location,
    action_details: generateActionDetails(action, npc, worldState),
    impact: calculateNPCActionImpact(action, npc),
    timestamp: new Date().toISOString()
  };
}

function generateFactionAction(faction, worldState) {
  const actions = ['recruitment', 'resource_acquisition', 'territory_expansion', 'diplomacy', 'conflict'];
  const action = actions[Math.floor(Math.random() * actions.length)];

  return {
    type: 'faction_action',
    subtype: action,
    faction_id: faction.id,
    faction_name: faction.name,
    action_details: generateFactionActionDetails(action, faction, worldState),
    impact: calculateFactionActionImpact(action, faction),
    affected_factions: determineAffectedFactions(faction, worldState.factions),
    timestamp: new Date().toISOString()
  };
}

function generateEconomicChange(worldState) {
  const changes = ['price_fluctuation', 'supply_shortage', 'demand_increase', 'trade_route_change'];
  const change = changes[Math.floor(Math.random() * changes.length)];

  return {
    type: 'economic_change',
    subtype: change,
    market_impact: calculateMarketImpact(change, worldState),
    affected_goods: generateAffectedGoods(change),
    description: generateEconomicDescription(change),
    duration: generateDuration(change),
    timestamp: new Date().toISOString()
  };
}

function generateMajorWorldEvent(worldState) {
  const events = ['monster_migration', 'trade_caravan_arrival', 'political_shift', 'magical_phenomenon', 'discovery'];
  const event = events[Math.floor(Math.random() * events.length)];

  return {
    type: 'major_world_event',
    subtype: event,
    description: generateMajorEventDescription(event, worldState),
    impact_level: 'high',
    affected_areas: determineAffectedAreas(event, worldState),
    duration: generateDuration(event),
    consequences: generateEventConsequences(event),
    timestamp: new Date().toISOString()
  };
}

// Helper functions
function calculateEnvironmentalImpact(change, environment) {
  const impacts = {
    weather_shift: 'minor',
    growth: 'minor',
    decay: 'moderate',
    discovery: 'moderate',
    natural_disaster: 'major'
  };
  return impacts[change] || 'minor';
}

function generateDuration(changeType) {
  const durations = {
    weather_shift: '1-6 hours',
    growth: 'permanent',
    decay: '1-3 days',
    discovery: 'permanent',
    natural_disaster: '1-7 days',
    recruitment: 'instant',
    resource_acquisition: 'instant',
    territory_expansion: 'permanent',
    diplomacy: '1-3 days',
    conflict: '1-7 days',
    price_fluctuation: '3-7 days',
    supply_shortage: '1-2 weeks',
    demand_increase: '1-2 weeks',
    trade_route_change: 'permanent',
    monster_migration: '1-2 weeks',
    trade_caravan_arrival: '3-5 days',
    political_shift: 'permanent',
    magical_phenomenon: '1-3 days',
    discovery: 'permanent'
  };
  return durations[changeType] || '1 day';
}

function generateActionDetails(action, npc, worldState) {
  switch (action) {
    case 'movement':
      const possibleLocations = worldState.locations?.map(loc => loc.id) || [];
      return {
        destination: possibleLocations[Math.floor(Math.random() * possibleLocations.length)],
        purpose: ['patrol', 'travel', 'exploration', 'fleeing'][Math.floor(Math.random() * 4)]
      };
    case 'interaction':
      return {
        target_type: ['npc', 'player', 'environment'][Math.floor(Math.random() * 3)],
        interaction_type: ['dialogue', 'trade', 'conflict', 'cooperation'][Math.floor(Math.random() * 4)]
      };
    default:
      return { complexity: 'simple' };
  }
}

function calculateNPCActionImpact(action, npc) {
  const impacts = {
    movement: 'minor',
    interaction: 'minor',
    skill_use: 'minor',
    resource_gathering: 'moderate',
    resting: 'minor'
  };
  return impacts[action] || 'minor';
}

function generateFactionActionDetails(action, faction, worldState) {
  return {
    scope: ['local', 'regional', 'global'][Math.floor(Math.random() * 3)],
    resources_committed: Math.floor(Math.random() * 100) + 10,
    success_chance: 0.3 + Math.random() * 0.6
  };
}

function calculateFactionActionImpact(action, faction) {
  const impacts = {
    recruitment: 'minor',
    resource_acquisition: 'moderate',
    territory_expansion: 'major',
    diplomacy: 'moderate',
    conflict: 'major'
  };
  return impacts[action] || 'minor';
}

function determineAffectedFactions(faction, allFactions) {
  return allFactions
    .filter(f => f.id !== faction.id && Math.random() < 0.6)
    .map(f => f.id);
}

function calculateMarketImpact(change, worldState) {
  return {
    price_change_percent: Math.floor(Math.random() * 40) - 20, // -20% to +20%
    volatility: Math.random(),
    affected_regions: ['all', 'local', 'regional'][Math.floor(Math.random() * 3)]
  };
}

function generateAffectedGoods(change) {
  const goods = ['food', 'weapons', 'armor', 'potions', 'materials', 'magic_items'];
  const count = Math.floor(Math.random() * 3) + 1;
  return goods.slice(0, count);
}

function generateEconomicDescription(change) {
  const descriptions = {
    price_fluctuation: 'Market prices shift due to changing supply and demand',
    supply_shortage: 'Resource shortage affects availability of goods',
    demand_increase: 'Increased demand drives market activity',
    trade_route_change: 'New trade opportunities emerge'
  };
  return descriptions[change] || 'Economic conditions change';
}

function generateMajorEventDescription(event, worldState) {
  const descriptions = {
    monster_migration: 'Monsters migrate to new territories',
    trade_caravan_arrival: 'A major trade caravan arrives in the region',
    political_shift: 'Political landscape undergoes significant changes',
    magical_phenomenon: 'Unusual magical events occur',
    discovery: 'New discoveries reshape understanding of the world'
  };
  return descriptions[event] || 'A major world event occurs';
}

function determineAffectedAreas(event, worldState) {
  const locationCount = Math.floor(Math.random() * 3) + 1;
  return worldState.locations?.slice(0, locationCount).map(loc => loc.id) || [];
}

function generateEventConsequences(event) {
  return {
    immediate: ['changed_world_state'],
    short_term: ['npc_reactions', 'faction_responses'],
    long_term: ['economic_impact', 'territory_changes']
  };
}

return [{
  json: {
    campaignId,
    evolutionEvents,
    eventCount: evolutionEvents.length,
    evolutionFactors,
    timestamp: new Date().toISOString()
  }
}];

