// Process DeepSeek narrative response and prepare world state updates
const eventData = $input.first().json;
const deepseekResponse = $input.last().json;

let narrativeData = {};
try {
  const content = deepseekResponse.choices[0].message.content;
  narrativeData = JSON.parse(content);
} catch (error) {
  console.error('Failed to parse DeepSeek response:', error);
  narrativeData = {
    narrative_description: 'The world continues to evolve with subtle changes.',
    player_hook: 'Opportunities for adventure may arise from these changes.',
    consequences: 'The world state will be affected in various ways.',
    dm_notes: 'Remember to integrate these changes into the ongoing narrative.'
  };
}

// Combine events with narratives
const enrichedEvents = eventData.evolutionEvents.map((event, index) => {
  const narrative = narrativeData.events?.[index] || narrativeData;

  return {
    ...event,
    narrative_description: narrative.narrative_description || `The world undergoes ${event.type}: ${event.subtype}`,
    player_hook: narrative.player_hook || 'This may present new opportunities for the party.',
    consequences: narrative.consequences || ['world_state_change'],
    dm_notes: narrative.dm_notes || 'Consider how this affects player stories.',
    processed: true
  };
});

// Calculate world state updates
const worldStateUpdates = calculateWorldStateUpdates(enrichedEvents, eventData.currentWorldState);

function calculateWorldStateUpdates(events, currentWorldState) {
  const updates = {
    locations: [],
    npcs: [],
    factions: [],
    economy: {},
    environment: {},
    new_events: events
  };

  events.forEach(event => {
    switch (event.type) {
      case 'environment_change':
        updates.environment = {
          current_weather: event.weather,
          active_phenomena: [event.subtype],
          affected_regions: event.affected_locations
        };
        break;

      case 'npc_action':
        updates.npcs.push({
          id: event.npc_id,
          action: event.subtype,
          new_location: event.action_details?.destination,
          status: 'active'
        });
        break;

      case 'faction_action':
        updates.factions.push({
          id: event.faction_id,
          action: event.subtype,
          affected_relationships: event.affected_factions,
          resources_change: event.action_details?.resources_committed
        });
        break;

      case 'economic_change':
        updates.economy = {
          market_conditions: event.subtype,
          price_changes: event.market_impact,
          affected_goods: event.affected_goods
        };
        break;

      case 'major_world_event':
        updates.new_events.push({
          ...event,
          priority: 'high',
          requires_player_attention: true
        });
        break;
    }
  });

  return updates;
}

return [{
  json: {
    campaignId: eventData.campaignId,
    evolution_cycle_id: `evolution_${Date.now()}`,
    original_events: eventData.evolutionEvents,
    enriched_events: enrichedEvents,
    world_state_updates: worldStateUpdates,
    narrative_summary: narrativeData.narrative_description || 'World evolution cycle completed',
    evolution_factors: eventData.evolutionFactors,
    timestamp: new Date().toISOString(),
    processed_by: 'world-evolution-engine'
  }
}];

// Generate evolution summary report
const evolutionData = $input.first().json;

const summary = {
  evolution_cycle_id: evolutionData.evolution_cycle_id,
  campaign_id: evolutionData.campaignId,
  processing_time: new Date().toISOString(),
  statistics: {
    total_events_generated: evolutionData.original_events.length,
    events_with_narratives: evolutionData.enriched_events.length,
    event_types: [...new Set(evolutionData.enriched_events.map(e => e.type))],
    high_impact_events: evolutionData.enriched_events.filter(e => e.impact_level === 'high').length,
    player_hooks_generated: evolutionData.enriched_events.filter(e => e.player_hook).length
  },
  world_changes: {
    locations_affected: evolutionData.world_state_updates.locations.length,
    npcs_affected: evolutionData.world_state_updates.npcs.length,
    factions_affected: evolutionData.world_state_updates.factions.length,
    economic_changes: Object.keys(evolutionData.world_state_updates.economy).length,
    environmental_effects: Object.keys(evolutionData.world_state_updates.environment).length
  },
  narrative_summary: evolutionData.narrative_summary,
  next_evolution_factors: {
    time_multiplier: Math.max(evolutionData.evolution_factors.time_multiplier * 0.8, 1),
    major_event_chance: Math.min(evolutionData.evolution_factors.major_event_chance * 1.1, 0.5)
  }
};

return [{ json: summary }];
